test("揃え先の左辺の近くまで運んでいる間は、その辺に線が出る", () => {
  /*
   * 右辺が 403 まで来て揃え先の左辺（400）へ 3px 寄る。線は揃え先の左辺に立ち、
   * 運んでいる artboard（上辺 40）から揃え先（下辺 380）までをまたぐ。
   */
  const dragging = moveSnapped(heldDrag(), pointerBy({ x: 103, y: 0 }), {
    carried: HomeDrawn,
    stationary: [StationaryDrawn],
  });

  const guideLine = Option.map(
    ArtboardDrag.snapGuides(dragging).horizontal,
    (guide) => guide.guideLine,
  );

  expect(guideLine).toEqual(
    Option.some({ left: 399, top: 40, width: 2, height: 340 }),
  );
});

test("揃え先の上辺の近くまで運んでいる間は、その辺に線が出る", () => {
  /*
   * 下辺が 298 まで来て揃え先の上辺（300）へ 2px 寄る。左右はどの線からも閾値の外。
   * 線は揃え先の上辺に寝て、運んでいる artboard（左辺 100）から揃え先（右辺 550）までをまたぐ。
   */
  const dragging = moveSnapped(heldDrag(), pointerBy({ x: 0, y: 158 }), {
    carried: HomeDrawn,
    stationary: [StationaryDrawn],
  });

  const guideLine = Option.map(
    ArtboardDrag.snapGuides(dragging).vertical,
    (guide) => guide.guideLine,
  );

  expect(guideLine).toEqual(
    Option.some({ left: 100, top: 299, width: 450, height: 2 }),
  );
});

test("運んでいる artboard に大きさが無ければ線を出さない", () => {
  // 寄せ量のテスト（artboard-drag.snap.test.ts）と同じ入力。大きさを測れていれば揃え先の左辺へ線が出る
  const snapped = ArtboardDrag.snappedAt(
    heldDrag(),
    pointerBy({ x: 5, y: 0 }),
    UnlaidOutDrawn,
  );

  expect(snapped.guides).toEqual(SideSnap.NoGuides);
});

test("揃う位置まで運んだあと、どこにも届かない位置まで動かし直すと、線が無くなる", () => {
  /*
   * 1 回目で 103 運んで 3px 寄せたので、`home` は 100 ずれた 200 に描かれている。
   * 2 回目は掴んでから 150 の位置で、行き先の右辺は 450 → どの線からも閾値の外。
   */
  const stationary = [StationaryDrawn];
  const dragging = moveSnapped(heldDrag(), pointerBy({ x: 103, y: 0 }), {
    carried: HomeDrawn,
    stationary,
  });

  const away = moveSnapped(dragging, pointerBy({ x: 150, y: 0 }), {
    carried: { ...HomeDrawn, left: 200 },
    stationary,
  });

  expect(ArtboardDrag.snapGuides(away)).toEqual(SideSnap.NoGuides);
});

test("他の artboard の辺に吸い付いている間は、その辺の位置に線が 1 本出る", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  pressPointer(artboardHandle("second"), { x: 0, y: 0 });
  movePointer(canvasContent(), { x: -29, y: 30 });

  // `first` の右辺に中心を合わせ、`first` の上辺 0 から `second` の下辺 170 までをまたぐ
  expect(snapGuides()).toHaveLength(1);
  expect(snapGuides()[0].getAttribute("style")).toContain(
    "left: 199px; top: 0px; width: 2px; height: 170px",
  );
});

test("揃え先から離れた位置で揃っている間も、揃え先との隙間の数値は出ない", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  // `first` の下辺 140 と `second` の上辺 200 の間は 60 空いている（ノードの移動なら「60」が出る）
  pressPointer(artboardHandle("second"), { x: 0, y: 0 });
  movePointer(canvasContent(), { x: -29, y: 200 });

  expect(snapGuides()).toHaveLength(1);
  expect(snapGapLabels()).toEqual([]);
});

test("吸い付いたあとにどの線からも遠い位置へ動かし直すと、線が消える", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  // 2 回目は左辺 292・右辺 492・上辺 40 で、どの artboard の辺と中心線からも閾値の外
  pressPointer(artboardHandle("second"), { x: 0, y: 0 });
  movePointer(canvasContent(), { x: -29, y: 30 });
  movePointer(canvasContent(), { x: 60, y: 40 });

  expect(snapGuides()).toHaveLength(0);
});

test("離すと線は消える", () => {
  renderCanvas({ selection: setupSelection() });
  drawnFollowingFrames();

  pressPointer(artboardHandle("second"), { x: 0, y: 0 });
  movePointer(canvasContent(), { x: -29, y: 30 });
  expect(snapGuides()).toHaveLength(1);
  releasePointer(canvasContent(), { x: -29, y: 30 });

  expect(snapGuides()).toHaveLength(0);
});

test("揃え先の辺の近くまで運ぶと、運び先がその辺に揃う位置へ寄る", () => {
  // 右辺が 403 まで来る量。揃え先の左辺（400）へ 3px 寄らなければ x は 203 になる
  const dragging = moveSnapped(heldDrag(), pointerBy({ x: 103, y: 0 }), {
    carried: HomeDrawn,
    stationary: [StationaryDrawn],
  });

  expect(ArtboardDrag.preview(dragging, CanvasView.create())).toEqual(
    Option.some({ name: "home", canvasPosition: { x: 200, y: 40 } }),
  );
});

test("他の artboard の辺の近くまで運んで離すと、その辺が揃う座標が書かれる", () => {
  const onRepositionArtboard = vi.fn();
  renderCanvas({ selection: setupSelection(), onRepositionArtboard });
  drawnFollowingFrames();

  // 左辺が `first` の右辺（200）の 3px 先まで来る量。寄せが無ければ x は 203 になる
  dragSecond({ x: -29, y: 30 });

  expect(onRepositionArtboard).toHaveBeenCalledWith("second", {
    x: 200,
    y: 30,
  });
});

test("辺のスナップの組を載せていない掴みでは、揃え先の近くでもガイド線は出ない", () => {
  const resize = grabbedAt(
    setupResizable(),
    { x: 1, y: 0.5 },
    { x: 300, y: 100 },
  );

  const tracked = NodeResize.trackedAt(resize, { x: 337, y: 100 }, setupView());

  expect(Option.map(tracked, ({ guides }) => guides)).toEqual(
    Option.some(SideSnap.NoGuides),
  );
});

