type ArtboardDrag =
  | Readonly<{ kind: "idle" }>
  | Readonly<{ kind: "held"; grab: ArtboardGrab }>
  | Readonly<{
      kind: "dragging";
      grab: ArtboardGrab;
      pointer: Offset;
      snapped: SideSnapped;
    }>;

const NoGuides = {
  horizontal: Option.none,
  vertical: Option.none,
} satisfies SnapGuides;
